        tmp[9] = tmp[6]*tmp[8];
        tmp[10] = -X[1];
        tmp[11] = p3d0_y + tmp[10];
        tmp[12] = tmp[11]*tmp[6];
        tmp[13] = -X[2];
        tmp[14] = p3d0_z + tmp[13];
        tmp[15] = tmp[14]*tmp[6];
        tmp[16] = X[7]*tmp[9] + X[8]*tmp[12] + X[9]*tmp[15];
        tmp[17] = tmp[16]*tmp[6];
        tmp[18] = X[9]*tmp[17];
        tmp[19] = X[6]*tmp[15] - X[7]*tmp[12] + X[8]*tmp[9];
        tmp[20] = tmp[19]*tmp[6];
        tmp[21] = X[6]*tmp[20];
        tmp[22] = X[6]*tmp[9];
        tmp[23] = X[9]*tmp[12];
        tmp[24] = X[8]*tmp[15];
        tmp[25] = tmp[22] + tmp[23] - tmp[24];
        tmp[26] = tmp[25]*tmp[6];
        tmp[27] = X[8]*tmp[26];
        tmp[28] = X[6]*tmp[12] + X[7]*tmp[15] - X[9]*tmp[9];
        tmp[29] = tmp[28]*tmp[6];
        tmp[30] = X[7]*tmp[29];
        tmp[31] = tmp[0] + tmp[18] + tmp[21] + tmp[27] - tmp[30];
        tmp[32] = cosf(X[19]);
        tmp[33] = cosf(X[20]);
        tmp[34] = tmp[32]*tmp[33];
        tmp[35] = sinf(X[19]);
        tmp[36] = sinf(X[21]);
        tmp[37] = tmp[35]*tmp[36];
        tmp[38] = sinf(X[20]);
        tmp[39] = cosf(X[21]);
        tmp[40] = tmp[32]*tmp[39];
        tmp[41] = tmp[38]*tmp[40];
        tmp[42] = tmp[37] + tmp[41];
        tmp[43] = -X[16];
        tmp[44] = X[6]*tmp[26] + X[7]*tmp[17] - X[8]*tmp[20] + X[9]*tmp[29] + tmp[43];
        tmp[45] = tmp[35]*tmp[39];
        tmp[46] = tmp[32]*tmp[36];
        tmp[47] = tmp[38]*tmp[46];
        tmp[48] = -tmp[45] + tmp[47];
        tmp[49] = -X[17];
        tmp[50] = -tmp[22] - tmp[23] + tmp[24];
        tmp[51] = tmp[50]*tmp[6];
        tmp[52] = X[6]*tmp[29] + X[7]*tmp[20] + X[8]*tmp[17] + X[9]*tmp[51] + tmp[49];
        tmp[53] = tmp[31]*tmp[34] + tmp[42]*tmp[44] + tmp[48]*tmp[52];
        tmp[54] = tmp[31]*tmp[38];
        tmp[55] = tmp[33]*tmp[44];
        tmp[56] = tmp[33]*tmp[52];
        tmp[57] = tmp[36]*tmp[56] + tmp[39]*tmp[55] - tmp[54];
        tmp[58] = 1.0/tmp[57];
        tmp[59] = fx*tmp[58];
        tmp[60] = tmp[53]*tmp[59];
        tmp[61] = tmp[33]*tmp[35];
        tmp[62] = powf(tmp[57], -2);
        tmp[63] = tmp[31]*tmp[61];
        tmp[64] = tmp[37]*tmp[38];
        tmp[65] = tmp[40] + tmp[64];
        tmp[66] = tmp[38]*tmp[45];
        tmp[67] = -tmp[46] + tmp[66];
        tmp[68] = fx*(tmp[44]*tmp[67] + tmp[52]*tmp[65] + tmp[63]);
        tmp[69] = tmp[62]*tmp[68];
        tmp[70] = -tmp[38]*tmp[69] - tmp[59]*tmp[61];
        tmp[71] = tmp[46] - tmp[66];
        tmp[72] = tmp[33]*tmp[39];
        tmp[73] = tmp[59]*tmp[71] + tmp[69]*tmp[72];
        tmp[74] = -tmp[40] - tmp[64];
        tmp[75] = tmp[33]*tmp[36];
        tmp[76] = tmp[59]*tmp[74] + tmp[69]*tmp[75];
        tmp[77] = 1.0/tmp[5];
        tmp[78] = 2*tmp[77];
